INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('nurilian-plant-people', 'Nurilian Plant-People', 'humanoid', 'rifts', 1, 'Mostly unprincipled or passive anarchist; good ones are uncommon and evil ones rare.', '{"IQ":"2D6+2","ME":"3D6+2","MA":"2D6+2","PS":"3D6+10","PP":"2D6","PE":"2D6+10","PB":"1D6+2","Spd":"1D6+5"}', 'PEx10', '1D6x10', 'PEx20', '6D6', NULL, 'M.D.C. is the P.E. attribute number x20, plus 1D4x10 per level of experience. On S.D.C. worlds it has the P.E. attribute number x10 in Hit Points plus 1D4x10 per level, and 1D6x10 S.D.C., natural A.R. 10 (the ar column). P.P.E. is 6D6 plus 1D4 per level. I.S.P. depends on the percentile psionics roll: a minor psychic has the M.E. attribute number +3D6 plus 1D6 per level, a major psychic the M.E. attribute number x3 plus 1D6+2 per level, and one in five has none. Speed is the walking figure after the Splugorth transmutation; an unaltered Plant-Person is rooted and has none.', 10, 8, '{"attacks":3}', 'Three physical or psionic attacks per melee round, plus one at levels 6, 12 and 18. The book prints no R.C.C. combat bonuses (it points to the natural abilities). Horror Factor 8 only for those who do not know them; none once their peaceful nature is known. Kept from sunlight for more than two hours, its attacks per melee, combat bonuses and speed are halved.', 'The R.C.C. skills, the five human skill picks and their later additions, and the Dragon experience table belong to the Plant-People class, not this row.', 'Four numbered racial abilities. (1) A gardener''s instinct for water, soil and light, which counts as the Botany skill and the Identify Plants and Animals skill, both at 80% +1% per level. (2) Communes with soil and plants to read the earth''s exact makeup and anything ailing a crop (blight, pests, drought or flooding, poison, heat), and can commune with True Earth Elementals and Earth Warlocks, who treat it as kin. (3) Splugorth Bio-Wizard transmutation gives a slave three rootlike legs to walk on, slowly and painfully; more than an hour of walking or labor hurts. (4) Lives on water, a few ounces of soil a day and sunlight: four hours a day keeps it healthy and six to ten is better; in the dark it works at full strength for two hours in all, which it can save for later, holds still to survive up to four days, then falls into a coma and dies after 1D6+6 days of total darkness (an overcast sky is enough light). Breathes carbon dioxide rather than oxygen, and tells the time by the sun to within 1D6 minutes. Takes no damage from cold down to freezing and half from harsher or magical cold (a tenth while it has hibernated at least two weeks); half damage from heat up to 100 F/38 C, full from fire of any kind. Immune to animal and humanoid diseases and most airborne gases and toxins, though plant diseases can reach it and it knows how to treat them. In sunlight it heals 6D6 points an hour and regrows a limb in about six months; with under four hours of sun a day it heals 1D6 a day and regrows four times as slowly. Given light, nutrients and water it can hibernate like a tree for 60 days +10 per level, aware only of the soil and plants nearby, and it keeps healing.', 'None.', 'Roll percentile: 01-50 a minor psychic with four Sensitive powers; 51-80 a major psychic with eight Sensitive powers plus Empathy at no I.S.P. cost; 81-00 no psionics.', '7-8 feet (2.1-2.4 m) tall, a little slimmer than a human; ancient ones grow to twice that', '200-300 lbs (90-135 kg)', '200 years; an unaltered one lives ten times as long', 'Wherever the Splugorth farm. About two million are on Rifts Earth, mostly in Atlantis, and only some ten thousand are free, scattered over the globe. It prefers any land with plenty of sun and water, such as South America and parts of Africa and Asia.', 'None as such; it would welcome Druids, South American Biomancers, Earth Warlocks, nature spirits and other naturalists, and most Shamans honor it as a nature spirit.', 'Only the Splugorth and their Minions. Others are taken one at a time, and those who ruin nature sadden and disgust it.', 'None; an R.C.C. offered as an NPC and, though the book advises against it, as a player character (the Plant-People class). It takes no O.C.C.', 'An intelligent, tree-like being with knotted arms, born rooted in the soil of a world that had no predators. Its own name for its people is lost; slavers call them Nurilians or simply Plant-People. The Splugorth spent centuries of magic teaching harvested Plant-People to walk, and millions now tend the fields of Atlantis and every other Splugorth world, prized because they sense exactly what a crop needs. Movement tires and pains them, yet the plants keep them content, they little understand animal society, law or morals, and few try to escape or join a resistance. It wants no armor, energy weapons or explosives, distrusts magic, and cannot use cybernetics made for mammals; few Bio-Wizard implants or symbiotes suit it. Value: 1D6x10,000 credits on average.', 'Rifts World Book 21: Splynn Dimensional Market p.82-85'),
('pythonan', 'Pythonan', 'humanoid', 'rifts', 1, 'Any, most often good or selfish; an evil Pythonan tends to be very evil.', '{"IQ":"2D6+8","ME":"3D6+6","MA":"2D6+6","PS":"2D6+8","PP":"3D6+6","PE":"3D6","PB":"3D6","Spd":"2D6"}', 'PE', '4D6+6', 'PE', '3D6+10', 'MEx3', 'A minor Mega-Damage creature on Rifts Earth: M.D.C. is the P.E. attribute number plus 1D6 per level of experience. On S.D.C. worlds it has the P.E. attribute number plus 1D6 per level in Hit Points, and 4D6+6 S.D.C., natural A.R. 8 (the ar column). P.P.E. is 3D6+10, or the magic O.C.C.''s if one is taken. I.S.P. is the M.E. attribute number x3 plus 2D6 per level (1D6 per level if it studies magic). Its Telekinetic Body Field adds a separate 30 M.D.C. shield (see natural abilities).', 8, 12, '{"attacks":4,"initiative":2,"dodge":3,"pull":3,"roll":3}', 'Four physical or psionic attacks per melee whatever its O.C.C., plus one at levels 4, 8 and 12. It cannot fight hand to hand in the usual way: weapons are worked by tail, mouth or telekinesis, and it parries only with a held weapon or telekinetic force. Printed as R.C.C. bonuses, on top of attribute bonuses (O.C.C. bonuses never apply): +2 initiative, +1 strike with bite, head butt or constriction, +2 strike and parry with the tail, +3 dodge, +3 pull punch, +3 roll with punch or impact, +2 save vs possession, +4 save vs Horror Factor. Weapons wielded by its Advanced Telekinesis get +1 initiative, +3 strike and +4 parry, and modern weapons fire with its W.P. bonuses and no penalty.', 'The O.C.C.s open to it, its halved related and secondary skills and the Dragon experience table belong to the Pythonan class, not this row; so does the Scholar/Philosopher or Artist variant that about 40% of Pythonans follow.', 'Keen smell, hearing and touch; feels small shifts in air temperature and reads it to within two degrees; tracks by smell alone at 70%. Heals twice as fast as a human. Climb 80%/60%, swim 60%, prowl 40%. +10% to all art skills, and +10% to literacy, new languages and Seduction. Two racial psionic specials: Advanced Telekinesis works like Telekinesis (Super) at double range and duration for half the I.S.P., holding up to four objects but working one at a time, and lets it wield ancient or modern weapons without penalty; the Telekinetic Body Field is a self-only shield of 30 M.D.C. plus 10 per level after the first, blocking physical and energy attacks (energy or physical magic included) while gas, poison, psionics and other magic pass through, for 10 I.S.P. and five minutes per level, cheaper to keep up than a Telekinetic Force Field. Weakness: cold-blooded. Below 70 F/21 C it is -2 to strike, parry and dodge and its initiative, attacks, speed and skills are halved; at freezing it shuts down to one attack and no bonuses; cold magic does it double damage.', 'None, unless it takes a magic O.C.C. (about 20% do, mainly Ley Line Walkers, Mystics, Shifters and Temporal Wizards); a magic Pythonan learns no psionic powers past those it is born with.', 'Master psychic; saves vs psionics on a 10 or higher. Telekinetic Acceleration Attack, Telekinetic Push, Telekinetic Lift, Telekinetic Punch, Levitation, Ectoplasm, Alter Aura, Deaden Senses, Impervious to Cold, Mind Block, Telepathy, Speed Reading, Hypnotic Suggestion and Telemechanics. One Physical power of choice at levels 1, 3, 6, 9, 12 and 15, and one Super-Psionic power at levels 5, 10 and 15. Plus its two racial specials, Advanced Telekinesis and the Telekinetic Body Field (natural abilities).', '7-9 feet (2.1-2.7 m) long', '150-250 lbs (67.5-112.5 kg)', '200 years', 'Warm country by preference, but almost anywhere, sheltering and heating its home as humanoids do. On Rifts Earth a couple of dozen live in North America (nine at Lazlo), a few in England and several dozen in China; several hundred came free with their own Shifters and Temporal Wizards, and far more as slaves.', 'Humans and D-Bees, though its looks often earn distrust; most are also at ease among dragons and creatures of magic, and, unless evil, ill at ease among demons and evil supernatural beings.', 'Evil reptilian beings, above all the Lyvorkkians, who can briefly seize the minds of intelligent reptiles; also the Splugorth and demons.', 'Takes an O.C.C. (the Pythonan class names which): most are scholars, philosophers, storytellers or artists, others Rogue Scientists, Vagabonds or practitioners of magic, all with reduced skills. Offered as an NPC villain and as an optional player character.', 'A great snake scaled in green, gold and black, which strangers take for a beast until it speaks. Pythonans are thoughtful, courteous and witty, love science, philosophy, art and argument, and do with a prehensile tail and telekinesis what others do with hands, from turning pages to sculpting and firing guns. Their lush home world is low on technology and high on learning. Calm and slow to anger, perhaps because they are cold-blooded, they get on with anyone who can look past their shape. Buyers want them as companions, tutors and artisans; few notice that the charming ones also make fine spies, thieves and killers. The Splugorth themselves find them dull. No implants by choice, though some slaves have Bio-Wizard limbs, symbiotes or parasites forced on them. Value: usually 200,000-600,000 credits, more for a famous artist or a bidding war.', 'Rifts World Book 21: Splynn Dimensional Market p.85-87'),
('rulian-translator', 'Rulian Translator', 'humanoid', 'rifts', 1, 'Any, most often good or selfish.', '{"IQ":"4D6","ME":"4D6","MA":"4D6","PS":"2D6+1","PP":"2D6+1","PE":"2D6+1","PB":"2D6+1","Spd":"3D6"}', 'PE', '4D6', NULL, '2D6', '1D6x10+ME', 'An S.D.C. being. Hit Points are the P.E. attribute number plus 1D6 per level of experience; S.D.C. is 4D6 plus any from physical skills. P.P.E. is 2D6. I.S.P. is 1D6x10 plus the M.E. attribute number, plus 2D6 per level after the first.', NULL, 6, NULL, 'Attacks and bonuses come from its hand to hand skill, usually Basic; the class must spend a related skill pick on one (Expert costs two, and Martial Arts and Assassin are closed to it). No R.C.C. combat bonuses; its only racial bonuses are to language skills. Horror Factor 6, only for those who have not met its kind.', 'The R.C.C. skills, related and secondary skill counts and the Rogue Scholar experience table belong to the Rulian Translator class, not this row; so do the Phase World starting languages.', 'Two numbered racial abilities, both at no I.S.P. cost. (1) Telepathic and empathic receiver: it feels the surface thoughts and, above all, the emotions behind any speech it hears, whether it wants to or not, though complex plans, secrets and subtle or mixed feelings slip past; it senses strong emotion approaching from 200 feet (61 m) +50 feet (15.2 m) per level, twice that range when the source is a god, a demon lord, an alien intelligence or an ancient dragon, without knowing whose it is until within 10 feet (3 m); reading one chosen person takes line of sight, concentration and 100 feet (30.5 m) or less. Base skill 83% +1% per level, and it makes its translations unusually faithful. (2) Instant languages: it understands any new spoken tongue at 98% and speaks it at 75% while in the company of someone using it; 60 hours of study over two weeks makes it permanent at 90%. It reads unknown writing at 75%, and a new literacy starts at base +20%. Its vocal cords span infrasonic to ultrasonic sound.', 'None.', 'Master psychic, though a very limited one: Meditation, Telepathy, Empathy, Speed Reading, Total Recall and Mind Bond, plus five Sensitive powers of choice and one more at levels 2, 5, 8, 12 and 15; Mind Block is not automatic. Saves vs most psionics on a 10 or higher, but needs 15 or higher against Telepathy, Empathic Transmission and possession.', 'Shorter than a human at the shoulder, but its long skull adds a foot: 6-7 feet (1.8-2.1 m) tall', '150-180 lbs (67.5-81 kg)', 'Up to 100 years, though most die at 20-35, by their own hand or a cruel master''s', 'Its home world is much like Earth, so it can live almost anywhere on Rifts Earth. A large population, free and slave, lives in the Three Galaxies, where Rulians know the six Trade Languages and two more at 98%.', 'None as such; most like the company of educated, like-minded humanoids.', 'The Splugorth, their Minions and every evil slaver.', 'None; an R.C.C. raised in the Splugorth pens as an interpreter. One born free may follow a scholar or adventurer O.C.C. with half the related and secondary skills (the Rulian Translator class). Offered as an NPC and as an optional player character.', 'A slight humanoid with an elongated cranium and a voice of extraordinary range, sold at Splynn as the living answer to the Megaverse''s many tongues: spells of speech unsettle people, telepathy offends them and machines garble meaning, so owning a Rulian interpreter is the fashion in Atlantis and the Three Galaxies. It is also a born linguist, mathematician and code-breaker. Under the cool manner is a poet. Forced to feel every cruelty its masters commit, many enslaved Rulians take their own lives; freed ones travel and turn what they see into verse and song, grander than the truth. Slaves own a set of clothes and little more, and free Rulians shun implants of every kind. Value: 100,000-150,000 credits on average, more when the fashion peaks.', 'Rifts World Book 21: Splynn Dimensional Market p.87-90');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'pythonan', 'Bite', '3D6', 0, NULL, 'S.D.C.; no venom.', 0),
('creature', 'pythonan', 'Head butt or jab', '2D4', 0, NULL, 'S.D.C., plus any P.S. damage bonus.', 1),
('creature', 'pythonan', 'Tail slash', '2D6', 0, NULL, 'S.D.C., plus any P.S. damage bonus.', 2),
('creature', 'pythonan', 'Constriction', '4D6', 0, NULL, 'S.D.C. per squeeze, each one melee action; wrapping the victim first takes two actions, and a strike roll of 18 or better pins its arms and legs.', 3);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 creatures are in' AS assertion, count(*) AS got, 3 AS want
  FROM creatures WHERE slug IN ('nurilian-plant-people', 'pythonan', 'rulian-translator');
SELECT 'and 3 of them are playable' AS assertion, count(*) AS got, 3 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('nurilian-plant-people', 'pythonan', 'rulian-translator');
SELECT 'the creatures carry 4 attacks' AS assertion, count(*) AS got, 4 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('nurilian-plant-people', 'pythonan', 'rulian-translator');

